using ImportOps.Domain.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace ImportOps.Infrastructure.Persistence.Configurations;

internal static class FinanceMap
{
    public static void Common<T>(EntityTypeBuilder<T> b,string table,string schema="fin") where T:class
        => b.ToTable(table,schema);
}

internal sealed class OperationBudgetConfiguration:IEntityTypeConfiguration<OperationBudget>
{
    public void Configure(EntityTypeBuilder<OperationBudget>b){b.ToTable("OPERATION_BUDGET","fin");b.HasKey(x=>x.OperationBudgetId);
        b.Property(x=>x.OperationBudgetId).HasColumnName("operation_budget_id");b.Property(x=>x.CompanyId).HasColumnName("company_id");b.Property(x=>x.OperationId).HasColumnName("operation_id");b.Property(x=>x.VersionNo).HasColumnName("version_no");b.Property(x=>x.BudgetStatus).HasColumnName("budget_status");b.Property(x=>x.BaseCurrencyCode).HasColumnName("base_currency_code");b.Property(x=>x.TotalEstimatedCost).HasColumnName("total_estimated_cost");b.Property(x=>x.TotalEstimatedService).HasColumnName("total_estimated_service");b.Property(x=>x.TotalEstimatedAmount).HasColumnName("total_estimated_amount");b.Property(x=>x.ApprovedAt).HasColumnName("approved_at");b.Property(x=>x.ApprovedByUserId).HasColumnName("approved_by_user_id");b.Property(x=>x.Notes).HasColumnName("notes");b.Property(x=>x.CreatedAt).HasColumnName("created_at");b.Property(x=>x.CreatedBy).HasColumnName("created_by");b.Property(x=>x.ModifiedAt).HasColumnName("modified_at");b.Property(x=>x.ModifiedBy).HasColumnName("modified_by");b.Property(x=>x.RowVer).HasColumnName("row_ver").IsRowVersion();}
}
